# shellcheck shell=bash disable=SC2034
# Spanish catalog for lib/worktrees.sh and the isolated-team messages of swarm, agents and the CLI
I18N+=(
  ["Unknown action: '%s' (list | create | remove | prune | status | merge | sync | clean)"]="Acción desconocida: '%s' (list | create | remove | prune | status | merge | sync | clean)"
  ["Linked '%s' from the main checkout"]="Enlazado '%s' desde el checkout principal"
  ['Team "%s" shares the zone folder: new executors join it without worktrees.']='El equipo «%s» comparte la carpeta de la zona: los nuevos ejecutores se suman sin worktrees.'
  ["'%s' is not a git repository with commits on a branch: the team shares the folder (no worktrees)."]="'%s' no es un repositorio git con commits en una rama: el equipo comparte la carpeta (sin worktrees)."
  ['Isolated team: each executor gets its own git worktree and branch from %s.']='Equipo aislado: cada ejecutor recibe su propio git worktree y una rama desde %s.'
  ['Executor: %s (%s) · branch %s']='Ejecutor: %s (%s) · rama %s'
  ["ISOLATED TEAM: each executor works on its own branch (%s), you stay on %s in the zone folder. See them with 'prama-agent worktree status', review with 'git diff %s...<branch>', integrate with 'prama-agent worktree merge <session>'."]="EQUIPO AISLADO: cada ejecutor trabaja en su propia rama (%s), tú te quedas en %s en la carpeta de la zona. Míralas con 'prama-agent worktree status', revisa con 'git diff %s...<rama>', integra con 'prama-agent worktree merge <sesión>'."
  ['An agent can only close its own team (%s).']='Un agente solo puede cerrar su propio equipo (%s).'
  ['Only the coordinator can close the team; ask it with prama-agent bus report.']='Solo el coordinador puede cerrar el equipo; pídeselo con prama-agent bus report.'
  ['🏁 The coordinator closed team "%s" (%d executor(s)).']='🏁 El coordinador cerró el equipo «%s» (%d ejecutor(es)).'
  ['(shared folder: the workers of this team have no worktrees)']='(carpeta compartida: los ejecutores de este equipo no tienen worktrees)'
  ['%d commit(s) to merge']='%d commit(s) por integrar'
  ['%d uncommitted']='%d sin commit'
  ['%d behind %s']='%d atrás de %s'
  ['up to date']='al día'
  ['(no worker worktrees)']='(sin worktrees de ejecutores)'
  ['Review: git diff %s...<branch> · integrate: prama-agent worktree merge <session>']='Revisar: git diff %s...<rama> · integrar: prama-agent worktree merge <sesión>'
  ["Unknown session: '%s'"]="Sesión desconocida: '%s'"
  ["'%s' has no worktree (shared folder)."]="'%s' no tiene worktree (carpeta compartida)."
  ["The zone's checkout is on '%s', not on the team's base '%s': switch it first (git -C %s switch %s)."]="El checkout de la zona está en '%s', no en la base del equipo '%s': cámbialo primero (git -C %s switch %s)."
  ['The checkout of %s has uncommitted changes: commit or stash them before merging.']='El checkout de %s tiene cambios sin commit: haz commit o stash antes de integrar.'
  ['%s has %d uncommitted file(s); only its commits are merged.']='%s tiene %d archivo(s) sin commit; solo se integran sus commits.'
  ['Nothing to merge: %s has no commits that %s lacks.']='Nada que integrar: %s no tiene commits que le falten a %s.'
  ['Merged %s into %s.']='%s integrada en %s.'
  ['Conflicts left in %s for you to resolve (then git commit): %s']='Conflictos pendientes en %s para que los resuelvas (luego git commit): %s'
  ['Merge of %s aborted, %s is unchanged. Conflicts: %s. Ask %s to run prama-agent worktree sync (merges %s into its branch), resolve them and commit; then merge again.']='Merge de %s abortado, %s no cambió. Conflictos: %s. Pide a %s que ejecute prama-agent worktree sync (trae %s a su rama), los resuelva y haga commit; luego integra de nuevo.'
  ['%s is %d commit(s) behind %s: prama-agent worktree sync %s']='%s está %d commit(s) atrás de %s: prama-agent worktree sync %s'
  ['%s has uncommitted changes: ask it to commit and run prama-agent worktree sync itself.']='%s tiene cambios sin commit: pídele que haga commit y ejecute él mismo prama-agent worktree sync.'
  ['%s is up to date with %s.']='%s está al día con %s.'
  ['Conflicts to resolve in your worktree (then git add + git commit): %s']='Conflictos por resolver en tu worktree (luego git add + git commit): %s'
  ['Sync of %s aborted (conflicts: %s); the worker has to run it and resolve them.']='Sync de %s abortado (conflictos: %s); el ejecutor debe ejecutarlo y resolverlos.'
  ['%d merged worktree(s) removed.']='%d worktree(s) integrados eliminados.'
  ['Kept %s: uncommitted changes in %s.']='Se conserva %s: cambios sin commit en %s.'
  ['Kept %s: it has commits not merged into %s (prama-agent worktree merge, or delete it by hand).']='Se conserva %s: tiene commits sin integrar en %s (prama-agent worktree merge, o bórrala a mano).'
  ['Which team? Give a zone (--team T), a coordinator or a worker session.']='¿Qué equipo? Indica una zona (--team T), un coordinador o la sesión de un ejecutor.'
  ["'%s' does not belong to a team."]="'%s' no pertenece a un equipo."
  ["There is no team \"%s\" in '%s'."]="No hay un equipo «%s» en '%s'."
  ["Zone '%s' has %d teams: give --team <name>."]="La zona '%s' tiene %d equipos: indica --team <nombre>."
  ['Team not found.']='Equipo no encontrado.'
  ["'%s' is another team's; you can only act on your own."]="'%s' es de otro equipo; solo puedes actuar sobre el tuyo."
  ['Team %s · integration branch %s']='Equipo %s · rama de integración %s'
  ['Only the coordinator of the team (%s) merges into the base branch.']='Solo el coordinador del equipo (%s) integra en la rama base.'
  ['Only %s itself or its coordinator can sync its branch.']='Solo %s o su coordinador pueden poner al día su rama.'
  ['--test requires a command']='--test requiere un comando'
  ['Usage: prama-agent worktree merge <worker session> [--test "<command>"] [--keep-conflicts]']='Uso: prama-agent worktree merge <sesión del ejecutor> [--test "<comando>"] [--keep-conflicts]'
  ['Running the tests: %s']='Corriendo los tests: %s'
  ['The tests failed after merging %s (code %d): the merge was undone, %s is unchanged. Send the failure to %s.']='Los tests fallaron tras integrar %s (código %d): se deshizo el merge, %s no cambió. Envía el fallo a %s.'
  ['Tests passed.']='Tests OK.'
)
